(function(root,factory){const api=factory();if(typeof module==='object')module.exports=api;else root.MartinsJornada=api;})(globalThis,()=>{
'use strict';
const KEYS={plans:'cm_planejamento_integrado_v1',frequency:'cm_frequencia_diaria_db',rdos:'cm_gestao_rdo_v5_db'};
const own=(o,k)=>Object.prototype.hasOwnProperty.call(o,k);
function date(s){if(typeof s!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(s)||s.startsWith('0000-'))throw Error('Data inválida');const parsed=new Date(s+'T12:00:00Z');if(!Number.isFinite(parsed.getTime())||parsed.toISOString().slice(0,10)!==s)throw Error('Data inválida');return s;}
function read(storage,key,fallback){const raw=storage.getItem(key);if(raw===null)return structuredClone(fallback);let value;try{value=JSON.parse(raw);}catch{throw Error('Dados inválidos em '+key+'. Conteúdo preservado; recupere o backup.');}if(!value||typeof value!=='object'||Array.isArray(value)!==Array.isArray(fallback))throw Error('Formato inválido em '+key);return value;}
function write(storage,key,value,expected){if(typeof MartinsPersistenciaRdo!=='undefined')MartinsPersistenciaRdo.guard(storage,key);const before=storage.getItem(key);if(expected!==undefined&&before!==expected)throw Error('Dados alterados em outra aba. Atualize a conferência.');read(storage,key,Array.isArray(value)?[]:{});if(before!==null)storage.setItem(key+'_backup_anterior',before);storage.setItem(key,JSON.stringify(value));}
function plan(rows,row,frequency){date(row.data);if(!row.funcionarioId||!row.obra||!Number.isFinite(row.horas)||row.horas<=0||row.horas>8||Math.round(row.horas*4)!==row.horas*4)throw Error('Informe funcionário, obra e horas em intervalos de 15 minutos (até 8h).');const status=frequency[row.data]?.[row.funcionarioId]?.status;if(status&&status!=='presente'&&status!=='sem_apontamento')throw Error('Funcionário indisponível: '+status);const next=rows.filter(x=>!(x.data===row.data&&x.funcionarioId===row.funcionarioId&&x.obra===row.obra));const total=next.filter(x=>x.data===row.data&&x.funcionarioId===row.funcionarioId).reduce((s,x)=>s+Number(x.horas),0)+row.horas;if(total>8)throw Error('Planejamento excede 8h no dia entre obras');return [...next,{...row}];}
function preview(rows,frequency,day){date(day);const grouped=new Map();for(const p of rows.filter(x=>x.data===day)){if(!grouped.has(p.funcionarioId))grouped.set(p.funcionarioId,[]);grouped.get(p.funcionarioId).push(p);}return [...grouped].map(([id,items])=>({id,items,existing:own(frequency[day]||{},id),total:items.reduce((s,x)=>s+x.horas,0)}));}
function confirm(rows,frequency,day,ids,{today=new Date().toLocaleDateString('en-CA',{timeZone:'America/Sao_Paulo'})}={}){date(day);date(today);if(day>today)throw Error('Data futura: mantenha no planejamento, sem confirmar frequência realizada');const next=structuredClone(frequency);const candidates=preview(rows,frequency,day);if(!next[day])next[day]={};for(const id of ids){const p=candidates.find(x=>x.id===id);if(!p||p.existing)throw Error('Registro já existe ou planejamento mudou. Atualize a conferência.');const x=p.items[0];if(!Number.isFinite(p.total)||p.total<=0||p.total>8)throw Error('Jornada inválida');next[day][id]={nome:x.nome,status:'presente',obra:p.items.length===1?x.obra:'Múltiplas obras',horas:p.total,...(p.items.length>1?{alocacoes:p.items.map(a=>({obra:a.obra,horas:a.horas}))}:{}),obs:'Conferido a partir do planejamento',origem:'planejamento_conferido'};}return next;}
function allocations(record){
 if(!record||record.status!=='presente')return [];
 const rows=record.alocacoes===undefined?[{obra:record.obra,horas:record.horas}]:record.alocacoes;
 if(!Array.isArray(rows)||!rows.length)throw Error('Alocações inválidas');
 const seen=new Set();let total=0;
 for(const a of rows){if(!a||!a.obra||seen.has(a.obra)||!Number.isFinite(Number(a.horas))||Number(a.horas)<=0)throw Error('Alocação inválida ou repetida');seen.add(a.obra);total+=Number(a.horas);}
 if(total>8||!Number.isFinite(Number(record.horas))||Math.abs(total-Number(record.horas))>0.001)throw Error('Total da jornada inconsistente');
 return rows.map(a=>({obra:a.obra,horas:Number(a.horas)}));
}
function rdoWorkers(frequency,day,work,employees){date(day);const workers=[];for(const [id,r] of Object.entries(frequency[day]||{})){
 const part=allocations(r).find(a=>a.obra===work);if(!part)continue;
 const e=employees.find(x=>String(x.id)===id);if(!e)throw Error('Funcionário sem vínculo no cadastro: '+id);
 workers.push({funcionarioId:id,nome:e.nome,funcao:e.cargo||e.funcao||'Funcionário',vinculo:e.vinculo||'Próprio (CLT)',horas:part.horas});
 }return workers;}
function mergeWorkers(current,incoming){const next=structuredClone(current);for(const row of incoming){const found=next.find(x=>x.funcionarioId===row.funcionarioId||String(x.nome).trim().toLocaleLowerCase('pt-BR')===row.nome.trim().toLocaleLowerCase('pt-BR'));if(found){if(Number(found.horas)!==row.horas)throw Error('Equipe já contém horas diferentes para '+row.nome);continue;}next.push(row);}return next;}
function auditDay(plans,frequency,rdos,day,employees){date(day);const rows=new Map(),warnings=[];
 const add=(id,name,work,hours,source)=>{const key=JSON.stringify([id,work]);if(!rows.has(key))rows.set(key,{funcionarioId:id,nome:name,obra:work,planejado:0,frequencia:0,rdoAprovado:0,rdoRascunho:0});rows.get(key)[source]+=hours;};
 for(const p of plans.filter(x=>x.data===day))add(p.funcionarioId,p.nome,p.obra,Number(p.horas),'planejado');
 for(const [id,r] of Object.entries(frequency[day]||{}))for(const part of allocations(r))add(id,r.nome,part.obra,part.horas,'frequencia');
 for(const rdo of rdos.filter(x=>x.data===day))for(const w of rdo.trabalhadores||[]){const matches=employees.filter(e=>w.funcionarioId?String(e.id)===String(w.funcionarioId):String(e.nome).trim().toLocaleLowerCase('pt-BR')===String(w.nome).trim().toLocaleLowerCase('pt-BR'));if(matches.length!==1){warnings.push('RDO '+rdo.id+': vínculo local ambíguo/ausente para '+w.nome);continue;}const hours=Number(w.horas);if(!Number.isFinite(hours)||hours<=0){warnings.push('Horas inválidas no RDO '+rdo.id);continue;}if(!['Aprovado','Rascunho'].includes(rdo.status)){warnings.push('Situação desconhecida no RDO '+rdo.id);continue;}add(String(matches[0].id),matches[0].nome,rdo.obra,hours,rdo.status==='Aprovado'?'rdoAprovado':'rdoRascunho');}
 const lines=[...rows.values()];for(const x of lines)x.situacao=Math.abs(x.planejado-x.frequencia)<0.001&&Math.abs(x.frequencia-x.rdoAprovado)<0.001?'Conforme':'Conferir divergência';
 return {lines,warnings};}
function validateRdoWorkers(workers){if(!Array.isArray(workers))throw Error('Equipe do RDO inválida');const result=[],seenIds=new Set(),seenNames=new Map();for(const w of workers){if(!w||typeof w!=='object')throw Error('Profissional inválido no RDO');const name=String(w.nome||'').trim();if(!name)continue;const h=Number(w.horas);if(!Number.isFinite(h)||h<=0||h>8)throw Error('Informe horas válidas (até 8h) para '+name);const employee=w.funcionarioId===undefined||w.funcionarioId===null?'':String(w.funcionarioId),normalized=name.toLocaleLowerCase('pt-BR'),previous=seenNames.get(normalized)||[];if((employee&&seenIds.has(employee))||previous.some(x=>!x||!employee))throw Error('Profissional repetido ou sem identificação distinta: '+name);if(employee)seenIds.add(employee);previous.push(employee);seenNames.set(normalized,previous);result.push({...structuredClone(w),horas:h});}return result;}
function canApprove(user){return Boolean(user&&user.status!=='Inativo'&&user.permissoes?.aprovarRdo!==false&&(user.perfil==='Master'||user.creaAtivo===true));}
function bindWorker(worker,employee){if(!employee||employee.id===undefined)throw Error('Selecione cadastro por ID');return {...worker,funcionarioId:String(employee.id),nome:employee.nome,funcao:employee.funcao||employee.cargo||'Operário',vinculo:employee.vinculo||worker.vinculo||'Próprio (CLT)'};}
const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function canReopen(user){return Boolean(user&&user.status!=='Inativo'&&user.permissoes?.reabrirRdo!==false&&(user.perfil==='Master'||(user.perfil==='Engenharia'&&(user.permissoes?.reabrirRdo===true||user.permissoes?.aprovarRdo===true))));}
return {KEYS,date,read,write,plan,preview,confirm,rdoWorkers,mergeWorkers,allocations,canReopen,canApprove,bindWorker,escapeHtml,auditDay,validateRdoWorkers};
});
